import{_ as a,o as e,c as t,a2 as i}from"./chunks/framework.Cj77QY92.js";const g=JSON.parse('{"title":"Raspberry Pi + MQTT: Basic Concepts and Installation","description":"Flash Raspberry Pi OS, bring the board online through a phone hotspot, then install Mosquitto and configure an authenticated MQTT broker — step by step.","frontmatter":{"title":"Raspberry Pi + MQTT: Basic Concepts and Installation","date":"2026-09-25T00:00:00.000Z","tags":["Raspberry Pi","MQTT","IoT"],"readingMinutes":6,"description":"Flash Raspberry Pi OS, bring the board online through a phone hotspot, then install Mosquitto and configure an authenticated MQTT broker — step by step."},"headers":[],"relativePath":"posts/raspberry-pi-mqtt-setup.md","filePath":"posts/raspberry-pi-mqtt-setup.md","lastUpdated":1791828061000}'),n={name:"posts/raspberry-pi-mqtt-setup.md"};function o(h,s,p,r,l,d){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="raspberry-pi-mqtt-basic-concepts-and-installation" tabindex="-1">Raspberry Pi + MQTT: Basic Concepts and Installation <a class="header-anchor" href="#raspberry-pi-mqtt-basic-concepts-and-installation" aria-label="Permalink to &quot;Raspberry Pi + MQTT: Basic Concepts and Installation&quot;">​</a></h1><p class="xq-lead"> A step-by-step log of turning a Raspberry Pi into an MQTT broker: flashing the SD card, getting the board online, installing Mosquitto, and securing it with a password. </p><h2 id="_1-flash-the-sd-card-first" tabindex="-1">1. Flash the SD card first <a class="header-anchor" href="#_1-flash-the-sd-card-first" aria-label="Permalink to &quot;1. Flash the SD card first&quot;">​</a></h2><p>Before doing anything else, the SD card has to be flashed on a PC. A USB card reader is the easiest way to connect it to the computer.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/raspberry1.jpg" alt="Flashing the SD card on a PC" loading="lazy"></p><p>Once the card is connected, download <strong>Raspberry Pi Imager</strong> from the official site: <a href="https://www.raspberrypi.com/software/" target="_blank" rel="noreferrer">Raspberry Pi software – Raspberry Pi</a>.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/raspberry2.png" alt="Raspberry Pi Imager" loading="lazy"></p><h2 id="_2-use-a-phone-hotspot-for-the-first-boot" tabindex="-1">2. Use a phone hotspot for the first boot <a class="header-anchor" href="#_2-use-a-phone-hotspot-for-the-first-boot" aria-label="Permalink to &quot;2. Use a phone hotspot for the first boot&quot;">​</a></h2><p>For the initial setup I used my phone&#39;s hotspot as the network.</p><div class="warning custom-block"><p class="custom-block-title">Remember</p><p>In the <strong>Customisation</strong> tab you have to fill in <em>every</em> field. Setting only the Wi-Fi name and password is not enough.</p></div><h2 id="_3-boot-the-pi-and-find-its-ip-address" tabindex="-1">3. Boot the Pi and find its IP address <a class="header-anchor" href="#_3-boot-the-pi-and-find-its-ip-address" aria-label="Permalink to &quot;3. Boot the Pi and find its IP address&quot;">​</a></h2><p>When flashing is done, put the SD card back into the Raspberry Pi, connect the power, and turn on the phone hotspot.</p><p>Then check the connection details of the hotspot on the phone and look for the Raspberry Pi&#39;s IP address. Mine was <code>10.24.199.94</code>.</p><h2 id="_4-ssh-into-the-pi" tabindex="-1">4. SSH into the Pi <a class="header-anchor" href="#_4-ssh-into-the-pi" aria-label="Permalink to &quot;4. SSH into the Pi&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> emola15@10.24.199.94</span></span></code></pre></div><p><code>emola15</code> is the username.</p><h2 id="_5-install-mosquitto" tabindex="-1">5. Install Mosquitto <a class="header-anchor" href="#_5-install-mosquitto" aria-label="Permalink to &quot;5. Install Mosquitto&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mosquitto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mosquitto-clients</span></span></code></pre></div><p>Then make sure Mosquitto starts automatically on boot:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mosquitto</span></span></code></pre></div><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/raspberry3.png" alt="Mosquitto installed on the Pi" loading="lazy"></p><h2 id="_6-create-a-broker-user" tabindex="-1">6. Create a broker user <a class="header-anchor" href="#_6-create-a-broker-user" aria-label="Permalink to &quot;6. Create a broker user&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mosquitto_passwd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/mosquitto/passwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pat</span></span></code></pre></div><p>This creates a new user <code>pat</code> and sets its password. You will be asked for the password twice; it is then encrypted and saved to <code>/etc/mosquitto/passwd</code>.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/RASPBERRY4.png" alt="Creating the password file" loading="lazy"></p><h2 id="_7-fix-ownership-and-permissions" tabindex="-1">7. Fix ownership and permissions <a class="header-anchor" href="#_7-fix-ownership-and-permissions" aria-label="Permalink to &quot;7. Fix ownership and permissions&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mosquitto:mosquitto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/mosquitto/passwd</span></span></code></pre></div><p>This changes the owner of the password file to the <code>mosquitto</code> user.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 640</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/mosquitto/passwd</span></span></code></pre></div><p>This allows read and write for the owner and read-only for the group.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/raspberry5.png" alt="Password file permissions" loading="lazy"></p><h2 id="_8-configure-mosquitto-conf" tabindex="-1">8. Configure mosquitto.conf <a class="header-anchor" href="#_8-configure-mosquitto-conf" aria-label="Permalink to &quot;8. Configure mosquitto.conf&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/mosquitto/mosquitto.conf</span></span></code></pre></div><p>Add these three settings:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">listener 1883 0.0.0.0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">allow_anonymous false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">password_file /etc/mosquitto/passwd</span></span></code></pre></div><p>The first line allows remote connections, the second line enables authentication, and the third line tells the broker whose credentials are allowed to publish and subscribe within the network — the user <code>pat</code> in my case.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/raspberry6.png" alt="Editing mosquitto.conf" loading="lazy"></p><h2 id="_9-restart-the-broker" tabindex="-1">9. Restart the broker <a class="header-anchor" href="#_9-restart-the-broker" aria-label="Permalink to &quot;9. Restart the broker&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mosquitto</span></span></code></pre></div><p>MQTT has to be restarted after the configuration file is modified.</p><h2 id="_10-publish-a-message-from-the-phone" tabindex="-1">10. Publish a message from the phone <a class="header-anchor" href="#_10-publish-a-message-from-the-phone" aria-label="Permalink to &quot;10. Publish a message from the phone&quot;">​</a></h2><p>Install an MQTT app on the phone and set the broker:</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/raspberry7.png" alt="Setting the broker in the MQTT app" loading="lazy"></p><p>Then set the topic and the message:</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/raspberry8.png" alt="Setting the topic and message" loading="lazy"></p><h2 id="_11-subscribe-on-the-pi-to-verify" tabindex="-1">11. Subscribe on the Pi to verify <a class="header-anchor" href="#_11-subscribe-on-the-pi-to-verify" aria-label="Permalink to &quot;11. Subscribe on the Pi to verify&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosquitto_sub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.24.199.94</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apple</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -P</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 88888888</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><p>This subscribes to the topic <code>apple</code> on the Raspberry Pi and waits for incoming messages.</p><p><img src="https://cdn.jsdelivr.net/gh/emolastuff15/blog_image@main/images/raspberry9.png" alt="Receiving the published message" loading="lazy"></p><p>With that, the whole loop works: the phone publishes, the broker on the Pi delivers, and <code>mosquitto_sub</code> prints the message.</p>`,50)])])}const k=a(n,[["render",o]]);export{g as __pageData,k as default};
